{"file_path":"src/cli.js","content":"#!/usr/bin/env node

const args = process.argv.slice(2);

// Validate command-line arguments
if (args.length < 1 || args.length > 2) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
  process.exit(2);
}

const mode = args[0];
if (!['waves', 'explain', 'pack'].includes(mode)) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
  process.exit(2);
}

let workerCount = 0;
if (mode === 'pack') {
  if (args.length !== 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
    process.exit(2);
  }
  const workerArg = args[1];
  // Validate worker count: must be positive integer, no sign, no leading zero
  if (!/^\d+$/.test(workerArg) || workerArg[0] === '0' || workerArg === '0') {
    process.stderr.write('error: workers must be a positive integer\n');
    process.exit(2);
  }
  workerCount = parseInt(workerArg, 10);
  if (workerCount === 0) {
    process.stderr.write('error: workers must be a positive integer\n');
    process.exit(2);
  }
}

// Read all input
let input = '';
process.stdin.on('data', chunk => {
  input += chunk;
});

process.stdin.on('end', () => {
  try {
    processInput(input, mode, workerCount);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exit(error.exitCode || 2);
  }
});

function processInput(input, mode, workerCount) {
  // Split on newlines and drop empty tail
  const lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const tasks = new Map();
  const deps = new Map();
  let lineNum = 0;

  // Parse input
  for (let i = 0; i < lines.length; i++) {
    lineNum = i + 1;
    let line = lines[i].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue;
    }

    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'task') {
      if (parts.length !== 3) {
        const err = new Error(`error: line ${lineNum}: expected task <name> <cost>`);
        err.exitCode = 2;
        throw err;
      }

      const name = parts[1];
      const costStr = parts[2];

      // Validate task name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        const err = new Error(`error: line ${lineNum}: invalid task name ${name}`);
        err.exitCode = 2;
        throw err;
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        const err = new Error(`error: line ${lineNum}: cost must be a non-negative integer`);
        err.exitCode = 2;
        throw err;
      }

      const cost = parseInt(costStr, 10);

      // Check for duplicate task
      if (tasks.has(name)) {
        const err = new Error(`error: line ${lineNum}: task ${name} is declared twice`);
        err.exitCode = 2;
        throw err;
      }

      tasks.set(name, cost);
      if (!deps.has(name)) {
        deps.set(name, []);
      }
    } else if (directive === 'dep') {
      if (parts.length < 2) {
        const err = new Error(`error: line ${lineNum}: expected dep <name> <dependency>...`);
        err.exitCode = 2;
        throw err;
      }

      const name = parts[1];
      const dependencies = parts.slice(2);

      if (!deps.has(name)) {
        deps.set(name, []);
      }

      const depList = deps.get(name);
      for (const dep of dependencies) {
        if (!depList.includes(dep)) {
          depList.push(dep);
        }
      }
    } else {
      const err = new Error(`error: line ${lineNum}: unknown directive ${directive}`);
      err.exitCode = 2;
      throw err;
    }
  }

  // Check for unknown tasks in dependencies
  const allTaskNames = Array.from(tasks.keys()).sort();
  for (const name of allTaskNames) {
    const depList = deps.get(name) || [];
    for (const dep of depList) {
      if (!tasks.has(dep)) {
        const err = new Error(`error: unknown task ${dep}`);
        err.exitCode = 2;
        throw err;
      }
    }
  }

  // Detect cycles using DFS
  detectCycles(tasks, deps, allTaskNames);

  // Calculate task depth (wave number)
  const depth = new Map();
  function calcDepth(name) {
    if (depth.has(name)) {
      return depth.get(name);
    }
    const depList = deps.get(name) || [];
    if (depList.length === 0) {
      depth.set(name, 0);
      return 0;
    }
    let maxDepth = 0;
    for (const dep of depList) {
      maxDepth = Math.max(maxDepth, calcDepth(dep));
    }
    depth.set(name, maxDepth + 1);
    return maxDepth + 1;
  }

  for (const name of allTaskNames) {
    calcDepth(name);
  }

  // Calculate start and finish times
  const startTime = new Map();
  const finishTime = new Map();

  function calcTimes(name) {
    if (startTime.has(name)) {
      return;
    }
    const depList = deps.get(name) || [];
    let start = 0;
    if (depList.length > 0) {
      for (const dep of depList) {
        calcTimes(dep);
      }
      start = Math.max(...depList.map(d => finishTime.get(d)));
    }
    startTime.set(name, start);
    finishTime.set(name, start + tasks.get(name));
  }

  for (const name of allTaskNames) {
    calcTimes(name);
  }

  const total =
    allTaskNames.length === 0 ? 0 : Math.max(...allTaskNames.map(n => finishTime.get(n)));

  // Perform requested operation
  if (mode === 'waves') {
    performWaves(allTaskNames, depth, total);
  } else if (mode === 'explain') {
    performExplain(allTaskNames, startTime, finishTime, depth, total);
  } else if (mode === 'pack') {
    performPack(allTaskNames, tasks, deps, startTime, depth, workerCount, total);
  }
}

function detectCycles(tasks, deps, allTaskNames) {
  const visited = new Set();
  const recStack = new Set();
  const path = [];

  function dfs(node) {
    visited.add(node);
    recStack.add(node);
    path.push(node);

    const depList = (deps.get(node) || []).sort();
    for (const dep of depList) {
      if (!visited.has(dep)) {
        if (dfs(dep)) return true;
      } else if (recStack.has(dep)) {
        // Found a cycle
        const cycleStart = path.indexOf(dep);
        const cycle = path.slice(cycleStart);
        cycle.push(dep);
        const cycleStr = cycle.join(' -> ');
        const err = new Error(`error: cycle: ${cycleStr}`);
        err.exitCode = 3;
        throw err;
      }
    }

    path.pop();
    recStack.delete(node);
    return false;
  }

  for (const name of allTaskNames) {
    if (!visited.has(name)) {
      dfs(name);
    }
  }
}

function performWaves(allTaskNames, depth, total) {
  if (allTaskNames.length === 0) {
    process.stdout.write(`total ${total}\n`);
    return;
  }

  const maxDepth = Math.max(...allTaskNames.map(n => depth.get(n)));

  for (let d = 0; d <= maxDepth; d++) {
    const waveNames = allTaskNames.filter(n => depth.get(n) === d);
    process.stdout.write(`wave ${d}: ${waveNames.join(' ')}\n`);
  }

  process.stdout.write(`total ${total}\n`);
}

function performExplain(allTaskNames, startTime, finishTime, depth, total) {
  for (const name of allTaskNames) {
    const s = startTime.get(name);
    const f = finishTime.get(name);
    const d = depth.get(name);
    process.stdout.write(`${name} start=${s} finish=${f} depth=${d}\n`);
  }
  process.stdout.write(`total ${total}\n`);
}

function performPack(allTaskNames, tasks, deps, startTime, depth, workerCount, total) {
  // Calculate priority: longest chain from this task (including itself)
  const priority = new Map();

  function calcPriority(name) {
    if (priority.has(name)) {
      return priority.get(name);
    }

    let maxDownstream = 0;
    for (const otherName of allTaskNames) {
      if (otherName !== name) {
        const otherDeps = deps.get(otherName) || [];
        if (otherDeps.includes(name)) {
          maxDownstream = Math.max(maxDownstream, calcPriority(otherName));
        }
      }
    }

    const p = tasks.get(name) + maxDownstream;
    priority.set(name, p);
    return p;
  }

  for (const name of allTaskNames) {
    calcPriority(name);
  }

  // Schedule tasks on workers
  const workerTasks = Array.from({ length: workerCount }, () => []);
  const workerFree = Array.from({ length: workerCount }, () => 0);
  const scheduled = new Set();
  const taskStart = new Map();
  const taskFinish = new Map();

  while (scheduled.size < allTaskNames.length) {
    // Find ready tasks (all dependencies finished)
    const ready = [];
    for (const name of allTaskNames) {
      if (scheduled.has(name)) continue;

      const depList = deps.get(name) || [];
      if (depList.every(d => taskFinish.has(d))) {
        ready.push(name);
      }
    }

    if (ready.length === 0) break;

    // Sort by priority (descending), then by name (ascending)
    ready.sort((a, b) => {
      const pa = priority.get(a);
      const pb = priority.get(b);
      if (pb !== pa) return pb - pa;
      return a.localeCompare(b);
    });

    // Assign to workers with earliest free time
    for (const name of ready) {
      // Find worker with smallest index among those with earliest free time
      let bestWorkerIdx = 0;
      let bestFreeTime = workerFree[0];

      for (let i = 1; i < workerCount; i++) {
        if (workerFree[i] < bestFreeTime) {
          bestFreeTime = workerFree[i];
          bestWorkerIdx = i;
        }
      }

      const start = bestFreeTime;
      const cost = tasks.get(name);
      const finish = start + cost;

      taskStart.set(name, start);
      taskFinish.set(name, finish);
      scheduled.add(name);

      workerTasks[bestWorkerIdx].push({ name, start, finish });
      workerFree[bestWorkerIdx] = finish;
    }
  }

  // Output worker schedules
  for (let i = 0; i < workerCount; i++) {
    process.stdout.write(`worker ${i}:`);
    for (const task of workerTasks[i]) {
      process.stdout.write(` ${task.name}@${task.start}-${task.finish}`);
    }
    process.stdout.write('\n');
  }

  const makespan = allTaskNames.length === 0 ? 0 : Math.max(...workerFree);
  process.stdout.write(`makespan ${makespan}\n`);
}
"}

